void lexer__read_char(lexer__Lexer* l) {
    {
    if (((*(l)).ch == 10)) {
    (*(l)).line = ((*(l)).line + 1);
    (*(l)).column = 1;
    } else {
    if (((*(l)).position > 0)) {
    (*(l)).column = ((*(l)).column + 1);
    } else {
    if (((*(l)).position == 0)) {
    if (((*(l)).ch != 0)) {
    (*(l)).column = ((*(l)).column + 1);
    }
    }
    }
    }
    if (((*(l)).read_position >= (*(l)).input.len)) {
    (*(l)).ch = 0;
    } else {
    (*(l)).ch = std_str_byte_at((*(l)).input, (*(l)).read_position);
    }
    (*(l)).position = (*(l)).read_position;
    (*(l)).read_position = ((*(l)).read_position + 1);
    }
}

